begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(31);
insert into auth.users(id,email) values ('77777777-7777-4777-8777-777777777777','motivation-a@example.invalid'),('88888888-8888-4888-8888-888888888888','motivation-b@example.invalid');
select ok((select relrowsecurity from pg_class where oid='public.reward_rules'::regclass),'Reward rules use RLS');
select ok((select relrowsecurity from pg_class where oid='public.freeze_purchases'::regclass),'Purchases use RLS');
select ok((select relrowsecurity from pg_class where oid='public.reminder_devices'::regclass),'Push devices use RLS');
set local role anon;
select is((select count(*)::integer from reward_rules),1,'Guests can load configured rules');
select throws_ok('select * from motivation_preferences','42501',null,'Guest cannot read private preferences');
select throws_ok('select * from freeze_purchases','42501',null,'Guest cannot read purchases');
select throws_ok($$select register_reminder_device('77777777-7777-4777-8777-777777777777','00000000-0000-4000-8000-000000000001','hash',1,null)$$,'42501',null,'Guest cannot register devices');
set local role service_role;
select lives_ok($$select save_motivation_preferences('77777777-7777-4777-8777-777777777777','{"dailyGoal":20,"reminderConsent":false,"reminderTime":"18:00","locale":"de","timeZone":"UTC"}',1000,500)$$,'Backend saves preferences');
select lives_ok($$select save_motivation_preferences('77777777-7777-4777-8777-777777777777',null,100,200)$$,'Old offline markers do not overwrite newer markers');
select lives_ok($$select save_motivation_preferences('77777777-7777-4777-8777-777777777777','{"dailyGoal":50}',0,0,true)$$,'A new device does not replace existing account preferences');
select is((select (preferences->>'dailyGoal')::integer from motivation_preferences),20,'Existing account goal wins over device defaults');
select is((select practiced_at from motivation_preferences),1000::bigint,'Practice marker stays monotone');
select is((select reminded_at from motivation_preferences),500::bigint,'Reminder marker stays monotone');
select lives_ok($$select register_reminder_device('77777777-7777-4777-8777-777777777777','00000000-0000-4000-8000-000000000001','hash',1,'ExpoPushToken[test]')$$,'Backend binds a token');
select ok((select lease_until>now()+interval '6 days' from reminder_devices),'Token registration has a bounded lease');
select throws_ok($$select retire_reminder_device('00000000-0000-4000-8000-000000000001','wrong',2)$$,'P0001',null,'Wrong installation capability cannot retire token');
select lives_ok($$select retire_reminder_device('00000000-0000-4000-8000-000000000001','hash',2)$$,'Own installation can retire token');
select is((select push_token from reminder_devices),null::text,'Retired token is removed');
select throws_ok($$select register_reminder_device('77777777-7777-4777-8777-777777777777','00000000-0000-4000-8000-000000000001','hash',1,'ExpoPushToken[old]')$$,'P0001',null,'Late registration cannot undo retirement');
select lives_ok($$select register_reminder_device('88888888-8888-4888-8888-888888888888','00000000-0000-4000-8000-000000000001','hash',3,'ExpoPushToken[new]')$$,'Same install can bind the next account');
select lives_ok($$select save_motivation_preferences('88888888-8888-4888-8888-888888888888','{"dailyGoal":20,"reminderConsent":true,"reminderTime":"18:00","locale":"de","timeZone":"UTC"}',0,0)$$,'New owner explicitly consents');
select ok(claim_reminder_delivery('88888888-8888-4888-8888-888888888888','2026-10-14','00000000-0000-4000-8000-000000000001'),'First daily attempt is claimed');
select ok(not claim_reminder_delivery('88888888-8888-4888-8888-888888888888','2026-10-14','00000000-0000-4000-8000-000000000001'),'Duplicate same-day attempt is refused');
select ok(not claim_reminder_delivery('88888888-8888-4888-8888-888888888888','2026-10-15','00000000-0000-4000-8000-000000000001'),'Travel cannot claim a second reminder within 23 hours');
set local role authenticated;
set local request.jwt.claims='{"sub":"77777777-7777-4777-8777-777777777777","role":"authenticated"}';
select is((select count(*)::integer from reminder_devices),0,'Earlier owner cannot read the rebound device');
select is((select count(*)::integer from motivation_preferences),1,'Own preferences are readable');
select throws_ok('update reward_rules set version=99','42501',null,'User cannot change economy');
select throws_ok('update reminder_devices set push_token=null','42501',null,'User cannot bypass token registration');
select throws_ok($$select save_motivation_preferences('77777777-7777-4777-8777-777777777777',null,0,0)$$,'42501',null,'User cannot call private preferences RPC');
reset role;
delete from auth.users where id='88888888-8888-4888-8888-888888888888';
select is((select count(*)::integer from reminder_devices),0,'Account deletion removes tokens');
select is((select count(*)::integer from reminder_deliveries),0,'Account deletion removes delivery history');
select * from finish();
rollback;
